def brute_force(nums: List[int], k: int) -> float:
    best = float("-inf")
    for i in range(len(nums)):
        total = 0
        for j in range(i, len(nums)):               # every subarray starting at i
            total += nums[j]
            if j - i + 1 >= k:
                best = max(best, total / (j - i + 1))
    return best

