class Solution:
    def findInMountainArray(self, target: int, mountainArr: "MountainArray") -> int:
        n = mountainArr.length()
        cache = {}

        def get(i: int) -> int:                        # memoised: an index is fetched once
            if i not in cache:
                cache[i] = mountainArr.get(i)
            return cache[i]

        lo, hi = 0, n - 1                              # 1) peak = first i with get(i) > get(i+1)
        while lo < hi:
            mid = (lo + hi) // 2
            if get(mid) < get(mid + 1):
                lo = mid + 1                           # still climbing
            else:
                hi = mid                               # at or past the summit
        peak = lo

        def search(lo: int, hi: int, ascending: bool) -> int:
            while lo <= hi:
                mid = (lo + hi) // 2
                v = get(mid)
                if v == target:
                    return mid
                if (v < target) == ascending:          # target lies to the right of mid
                    lo = mid + 1
                else:
                    hi = mid - 1
            return -1

        idx = search(0, peak, True)                    # 2) left slope first: smaller index
        if idx != -1:
            return idx
        return search(peak + 1, n - 1, False)          # 3) right slope, descending order

class Solution:
    def maxRunTime(self, n: int, batteries: List[int]) -> int:
        def can(t: int) -> bool:
            # each battery gives at most t minutes to the n*t minute-slots
            return sum(min(b, t) for b in batteries) >= n * t

        lo, hi = 0, sum(batteries) // n          # hi: every minute of charge used, no waste
        while lo < hi:                           # find the LAST t with can(t)
            mid = (lo + hi + 1) // 2             # round up so lo = mid always progresses
            if can(mid):
                lo = mid                         # feasible: try longer
            else:
                hi = mid - 1                     # infeasible: must run shorter
        return lo

