class Solution:
    def outerTrees(self, trees: List[List[int]]) -> List[List[int]]:
        def cross(o, a, b) -> int:                   # (a - o) x (b - o)
            return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

        pts = sorted(map(tuple, trees))
        lower = []
        for p in pts:                                # left -> right along the bottom
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) < 0:
                lower.pop()                          # clockwise turn: middle point is inside
            lower.append(p)
        upper = []
        for p in reversed(pts):                      # right -> left along the top
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) < 0:
                upper.pop()
            upper.append(p)
        return [list(p) for p in set(lower + upper)]  # ends appear in both chains

class Solution:
    def countDigitOne(self, n: int) -> int:
        total, p = 0, 1                              # p = weight of the current position
        while p <= n:
            high, cur, low = n // (p * 10), (n // p) % 10, n % p
            total += high * p                        # full cycles above this position
            if cur > 1:
                total += p                           # partial cycle already passed its 1-run
            elif cur == 1:
                total += low + 1                     # inside the 1-run: 0..low below it
            p *= 10
        return total
